/* updateMasterMdCpRestrcCompanyPop */
UPDATE ICOMCMPY
SET
	MDM_CONFIRM_TYPE = 'F',
	MDM_NOTE  = #{st_panalty_remark}
WHERE COM_CODE  = #{st_com_code}

/* insertMasterMdCpRestrcCompanyPop */ INSERT INTO ICOMCOD3 ( BUYER, TYPE, CODE1, CODE2, TEXT1, TEXT2, TEXT3, TEXT4, VALUE1, FLAG, ADD_USER_ID, ADD_DATE ) ( SELECT 'KRKORE0001', 'BNOT', #{st_buyer}, #{st_com_code}, DECODE(#{st_buyer}, 'ALL', '전체고객사', COM_NAME_LOC), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}), '', '', '1', 'P', #{st_user_id}, TO_CHAR(SYSDATE,'YYYYMMDD') FROM ICOMCMPY WHERE STATUS IN ('C','R')
AND COM_CODE IN ('KRKORE0001' )
AND COM_CODE IN (#{st_buyer})
)
